/// <summary>
///     The <c>AVACreateContactPersonBasedOnGABUIBuilder</c> class is the UI builder class for <c>Creating contact persons based on GAB</c>
/// </summary>
class AVACreateContactPersonBasedOnGABUIBuilder extends SysOperationAutomaticUIBuilder
{
    AVACreateContactPersonBasedOnGABContract    contract;

    DialogField df_BusRelAccount;
    DialogField df_BusRelTypeId;

    DialogField df_DirPartyRecId;
    DialogField df_DirPartyType;
    DialogField df_DirPartyRoleType;

}

Method.Source:
/// <summary>
///     AVA <c>getContract</c> method.
/// </summary>
/// <returns>
///     <c>AVACreateContactPersonBasedOnGABContract</c> as return value
/// </returns>
private AVACreateContactPersonBasedOnGABContract getContract()
{
    if(!contract)
    {
        contract = this.dataContractObject() as AVACreateContactPersonBasedOnGABContract;
    }

    return contract;
}

/// <summary>
///     AVA <c>getFromDialog</c> method.
/// </summary>
public void getFromDialog()
{
    super();

    this.getContract().parmBusRelAccount(df_BusRelAccount.value());
    this.getContract().parmBusRelTypeId(df_BusRelTypeId.value());

    this.getContract().parmDirPartyRecId(df_DirPartyRecId.value());
    this.getContract().parmDirPartyType(df_DirPartyType.value());
    this.getContract().parmDirPartyRoleType(df_DirPartyRoleType.value());
}

/// <summary>
///    AVA <c>build</c> method.
/// </summary>
public void build()
{
    super();

    this.getReferencesToDialogControls();

    this.modifyDialogFields();
}

/// <summary>
///    AVA <c>postBuild</c> method.
/// </summary>
public void postBuild()
{
    super();

    this.getReferencesToDialogControls();

    df_DirPartyType.visible(true);
    df_DirPartyRoleType.visible(true);

    if(df_BusRelTypeId)
    {
        df_BusRelTypeId.allowEdit(false);
        df_BusRelTypeId.skip(true);
    }
    if(df_DirPartyRecId)
    {
        df_DirPartyRecId.allowEdit(false);
        df_DirPartyRecId.skip(true);
    }
    if(df_DirPartyType)
    {
        df_DirPartyType.allowEdit(false);
        df_DirPartyType.skip(true);
    }
    if(df_DirPartyRoleType)
    {
        df_DirPartyRoleType.allowEdit(false);
        df_DirPartyRoleType.skip(true);
    }
}

/// <summary>
///    AVA <c>postRun</c> method.
/// </summary>
public void postRun()
{
    super();

    //modified
    df_BusRelAccount.registerOverrideMethod(methodStr(FormStringControl, modified),
                                            methodStr(AVACreateContactPersonBasedOnGABUIBuilder, modifiedBusRelAccount),
                                            this);
}

/// <summary>
///    AVA <c>modifiedDirPartyRoleType</c> method.
/// </summary>
/// <param name="_dialogField">
///    <c>FormInt64Control</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modifiedBusRelAccount(FormStringControl _dialogField)
{
    smmBusRelAccount    locsmmBusRelAccount;
    smmBusRelTable      locsmmBusRelTable;
    DirPartyTable       locDirPartyTable;

    locsmmBusRelAccount = _dialogField.valueStr();
    locsmmBusRelTable   = smmBusRelTable::find(locsmmBusRelAccount);
    locDirPartyTable    = DirPartyTable::findRec(locsmmBusRelTable.Party);

    df_BusRelTypeId.value(locsmmBusRelTable.BusRelTypeId);
    df_DirPartyRecId.value(locsmmBusRelTable.Party);
    df_DirPartyType.value(locDirPartyTable.type());
    df_DirPartyRoleType.value(this.getContract().parmDirPartyRoleType());

    this.modifyDialogFields();

    return true;
}

/// <summary>
///    AVA <c>modifyDialogFields</c> method.
/// </summary>
private void modifyDialogFields()
{
    df_DirPartyRecId.allowEdit(false);
    df_DirPartyType.allowEdit(false);
    df_DirPartyRoleType.allowEdit(false);
}

/// <summary>
///    AVA <c>getReferencesToDialogControls</c> method.
/// </summary>
private void getReferencesToDialogControls()
{
    // get references to dialog controls after creation
    df_BusRelAccount            = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVACreateContactPersonBasedOnGABContract, parmBusRelAccount));
    df_BusRelTypeId             = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVACreateContactPersonBasedOnGABContract, parmBusRelTypeId));
    df_DirPartyRecId            = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVACreateContactPersonBasedOnGABContract, parmDirPartyRecId));
    df_DirPartyType             = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVACreateContactPersonBasedOnGABContract, parmDirPartyType));
    df_DirPartyRoleType         = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVACreateContactPersonBasedOnGABContract, parmDirPartyRoleType));
}
